$pass=0;$fail=0;
function a15($name,$fn){global $pass,$fail;try{$fn();$pass++;echo "PASS $name\n";}catch(Throwable $e){$fail++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function eq15($a,$b){if($a!==$b){throw new RuntimeException(json_encode([$a,$b],JSON_UNESCAPED_UNICODE));}}
function no15($code,$fn){try{$fn();}catch(Problem $e){eq15($e->errorCode,$code);return;}throw new RuntimeException('Expected '.$code);}
$a=$db->one("SELECT id AS admin_id,user_id FROM m_admin_accounts WHERE username='test_admin'")+['realm'=>'admin'];
