$mentor=Security::id();$db->run('INSERT INTO m_users(id,phone,phone_verified_at,display_name,created_at,updated_at) VALUES(?,?,?,?,?,?)',[$mentor,'099'.random_int(10000000,99999999),time(),'آزمون اطلس',time(),time()]);$db->run("INSERT INTO m_mentors(user_id,headline,bio,status,invited_at,accepted_at,updated_at) VALUES(?,?,?,'active',?,?,?)",[$mentor,'معرفی','شرح آزمون',time(),time(),time()]);
