$topic=Security::id();$topic2=Security::id();$issue=Security::id();foreach([[$topic,'topic'],[$topic2,'topic'],[$issue,'issue']] as [$id,$kind]){$db->run('INSERT INTO m_terms(id,kind,title) VALUES(?,?,?)',[$id,$kind,$kind.'-'.Security::id()]);}
$base=['version_id'=>$vid,'status'=>'approved','is_primary'=>1];
$location=$base+['kind'=>'place','province_id'=>$province,'county_id'=>$county];
$link=$base+['kind'=>'organization','org_id'=>$org,'raw_name'=>'PRIVATE_RAW','internal_note'=>'PRIVATE_NOTE','evidence'=>'PRIVATE_EVIDENCE'];
a15('reference dataset contains 31 provinces and county hierarchy',fn()=>eq15(count($atlas->places()),31));
a15('county cannot be assigned to another province',fn()=>no15('INVALID_PLACE',fn()=>$atlas->location($province,$otherCounty)));
a15('province-only location is allowed',fn()=>eq15($atlas->location($province,''),[$province,null]));
a15('ordinary users cannot create an organization',fn()=>no15('ACCESS_DENIED',fn()=>$atlas->saveOrganization($user,$orgData)));
a15('organization has no account or login identity',fn()=>eq15((int)$db->run('SELECT COUNT(*) FROM m_users WHERE id=?',[$org])->fetchColumn(),0));
a15('organization without public attribution remains private',fn()=>no15('NOT_FOUND',fn()=>$atlas->organization($org)));
a15('exact duplicate in same place is rejected',fn()=>no15('DUPLICATE_ORGANIZATION',fn()=>$atlas->saveOrganization($a,$orgData)));
$second=$atlas->saveOrganization($a,array_replace($orgData,['province_id'=>$province,'county_id'=>$county]));
a15('same name in different county stays a separate identity',fn()=>eq15($second!==$org,true));
$atlas->attribution($a,array_replace($link,['status'=>'proposed']));
a15('proposed attribution never appears publicly',fn()=>eq15($atlas->publicLinks($vid)['organizations'],[]));
$atlas->attribution($a,$link);$atlas->attribution($a,$location);
a15('approved public attribution displays the real organization',fn()=>eq15($atlas->organization($org)['experiences']['total'],1));
a15('private attribution notes are excluded from public DTO',function()use($atlas,$vid){$json=json_encode($atlas->publicLinks($vid));foreach(['PRIVATE_RAW','PRIVATE_NOTE','PRIVATE_EVIDENCE'] as $secret){eq15(str_contains($json,$secret),false);}});
a15('experience geography is independent from organization location',function()use($atlas,$province,$other,$org,$mentor){eq15($atlas->discover(['province'=>$province,'mentor_id'=>$mentor],true)['total'],1);eq15($atlas->discover(['province'=>$province,'layer'=>'organizations','organization_id'=>$org],true)['total'],0);eq15($atlas->discover(['province'=>$other,'layer'=>'organizations','organization_id'=>$org],true)['total'],1);});
