a15('organization merge cannot form a cycle',fn()=>no15('INVALID_MERGE',fn()=>$atlas->merge($a,$second,$org)));
a15('operational membership is never evidence of public mentor association',function()use($atlas,$a,$orgData,$mentor,$db){$o=$atlas->saveOrganization($a,array_replace($orgData,['name'=>'Private membership '.Security::id()]));$db->run('INSERT INTO m_memberships(org_id,user_id) VALUES(?,?)',[$o,$mentor]);no15('NOT_FOUND',fn()=>$atlas->organization($o));});
a15('canonical graph edges are projected without duplicate storage',function()use($k,$eid){$edges=$k->projectedEdges($eid);eq15(count(array_filter($edges,fn($e)=>$e['type']==='EXPERIENCE_ABOUT_TOPIC')),2);eq15(count(array_filter($edges,fn($e)=>$e['type']==='MENTOR_OWNS_EXPERIENCE')),1);});
