a15('event property allowlist rejects raw private input',fn()=>eq15($events->record($user,'EXPERIENCE_VIEWED','EXPERIENCE',$eid,['phone'=>'PRIVATE_PHONE'],'bad'),false));
a15('valid interaction is private and idempotent',function()use($events,$user,$eid,$db){$before=(int)$db->run('SELECT COUNT(*) FROM m_interaction_events')->fetchColumn();$events->record($user,'EXPERIENCE_VIEWED','EXPERIENCE',$eid,[],'same');$events->record($user,'EXPERIENCE_VIEWED','EXPERIENCE',$eid,[],'same');eq15((int)$db->run('SELECT COUNT(*) FROM m_interaction_events')->fetchColumn(),$before+1);});
